// And groups predicates with the AND operator between them.
func And(predicates ...predicate.MenuLinkDef) predicate.MenuLinkDef {
	return predicate.MenuLinkDef(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.MenuLinkDef) predicate.MenuLinkDef {
	return predicate.MenuLinkDef(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.MenuLinkDef) predicate.MenuLinkDef {
	return predicate.MenuLinkDef(sql.NotPredicates(p))
}
